//! T5: compare a built database with the independent oracle files
//! (`pipeline/tests/expected/kjv-chapters.tsv` and `kjv-q.tsv`, generated by
//! `docs/pipeline/survey-scripts/oracle_kjv.py`; DESIGN.md 11.1). The
//! database side is serialised here the same way the generator does, and
//! compared line by line, so a mismatch names the chapter or the `q_ord`.
//! For `kjv-q.tsv` each `q_ord`'s pieces are read back and joined in verse
//! order; the oracle computed the same text by tag stripping.

use std::collections::BTreeMap;

use rusqlite::Connection;

use crate::error::{Collector, Error, Result};
use crate::sources::sha256_hex;

fn sqlerr(e: rusqlite::Error) -> Error {
    Error::new("T5", format!("SQLite: {e}"))
}

/// The `# source: … sha256 <hex>` and `# generator: <path> sha256 <hex>`
/// header values of an oracle file.
pub fn header_value(tsv: &str, key: &str) -> Option<String> {
    tsv.lines()
        .take_while(|l| l.starts_with('#'))
        .find(|l| l.starts_with(&format!("# {key}:")))
        .and_then(|l| l.rsplit(' ').next())
        .map(str::to_string)
}

fn rows(tsv: &str) -> Vec<&str> {
    tsv.lines().filter(|l| !l.starts_with('#')).collect()
}

/// The database's kjv-chapters.tsv lines (without header).
pub fn chapter_lines(conn: &Connection) -> std::result::Result<Vec<String>, Error> {
    let mut books: BTreeMap<i64, String> = BTreeMap::new();
    let mut st = conn.prepare("SELECT ord, osis FROM book").map_err(sqlerr)?;
    for r in st
        .query_map([], |r| Ok((r.get(0)?, r.get(1)?)))
        .map_err(sqlerr)?
    {
        let (o, n) = r.map_err(sqlerr)?;
        books.insert(o, n);
    }
    // (book, chapter) -> accumulators, in id order.
    struct Acc {
        verses: usize,
        text: Vec<String>,
        marks: Vec<String>,
        red: Vec<String>,
        words: Vec<String>,
    }
    let mut ch: BTreeMap<(i64, i64), Acc> = BTreeMap::new();
    let mut st = conn
        .prepare("SELECT book, chapter, verse, text FROM verse ORDER BY id")
        .map_err(sqlerr)?;
    let mut q = st.query([]).map_err(sqlerr)?;
    while let Some(r) = q.next().map_err(sqlerr)? {
        let a = ch
            .entry((r.get(0).map_err(sqlerr)?, r.get(1).map_err(sqlerr)?))
            .or_insert(Acc {
                verses: 0,
                text: Vec::new(),
                marks: Vec::new(),
                red: Vec::new(),
                words: Vec::new(),
            });
        a.verses += 1;
        a.text.push(r.get(3).map_err(sqlerr)?);
    }
    let key = |id: i64| (id / 1_000_000, (id / 1000) % 1000);
    let mut st = conn
        .prepare("SELECT verse_id, start_cp, end_cp, kind FROM mark ORDER BY verse_id, n")
        .map_err(sqlerr)?;
    let mut q = st.query([]).map_err(sqlerr)?;
    while let Some(r) = q.next().map_err(sqlerr)? {
        let id: i64 = r.get(0).map_err(sqlerr)?;
        let (s, e, k): (i64, i64, String) = (
            r.get(1).map_err(sqlerr)?,
            r.get(2).map_err(sqlerr)?,
            r.get(3).map_err(sqlerr)?,
        );
        if let Some(a) = ch.get_mut(&key(id)) {
            a.marks.push(format!("{}:{s}-{e}:{k}", id % 1000));
        }
    }
    let mut st = conn
        .prepare("SELECT verse_id, start_cp, end_cp, q_ord FROM red_piece ORDER BY verse_id, n")
        .map_err(sqlerr)?;
    let mut q = st.query([]).map_err(sqlerr)?;
    while let Some(r) = q.next().map_err(sqlerr)? {
        let id: i64 = r.get(0).map_err(sqlerr)?;
        let (s, e, o): (i64, i64, i64) = (
            r.get(1).map_err(sqlerr)?,
            r.get(2).map_err(sqlerr)?,
            r.get(3).map_err(sqlerr)?,
        );
        if let Some(a) = ch.get_mut(&key(id)) {
            a.red.push(format!("{}:{s}-{e}:{o}", id % 1000));
        }
    }
    let mut st = conn
        .prepare(
            "SELECT w.verse_id, w.n, w.start_cp, w.end_cp,
                    (SELECT group_concat(kk.key, '+' ORDER BY kk.k) FROM word_key kk
                      WHERE kk.verse_id = w.verse_id AND kk.n = w.n)
               FROM word w ORDER BY w.verse_id, w.n",
        )
        .map_err(sqlerr)?;
    let mut q = st.query([]).map_err(sqlerr)?;
    while let Some(r) = q.next().map_err(sqlerr)? {
        let id: i64 = r.get(0).map_err(sqlerr)?;
        let (n, s, e): (i64, i64, i64) = (
            r.get(1).map_err(sqlerr)?,
            r.get(2).map_err(sqlerr)?,
            r.get(3).map_err(sqlerr)?,
        );
        let keys: Option<String> = r.get(4).map_err(sqlerr)?;
        if let Some(a) = ch.get_mut(&key(id)) {
            a.words.push(format!(
                "{}:{n}:{s}-{e}:{}",
                id % 1000,
                keys.unwrap_or_default()
            ));
        }
    }
    let dash = |v: &[String]| {
        if v.is_empty() {
            "-".to_string()
        } else {
            v.join(" ")
        }
    };
    Ok(ch
        .iter()
        .map(|((b, c), a)| {
            format!(
                "{}.{c}\t{}\t{}\t{}\t{}\t{}",
                books.get(b).cloned().unwrap_or_default(),
                a.verses,
                sha256_hex(a.text.join("\n").as_bytes()),
                dash(&a.marks),
                dash(&a.red),
                sha256_hex(a.words.join("\n").as_bytes())
            )
        })
        .collect())
}

/// (book, verses, first verse id, last verse id, red code points, red SHA-256).
pub type QRecord = (String, usize, i64, i64, usize, String);

/// Per q_ord: (book of the first piece, verses touched, first verse id, last
/// verse id, red code points, SHA-256 of the joined red text).
pub fn q_records(conn: &Connection) -> std::result::Result<BTreeMap<i64, QRecord>, Error> {
    let mut st = conn
        .prepare(
            "SELECT r.q_ord, r.verse_id, b.osis, substr(v.text, r.start_cp + 1, r.end_cp - r.start_cp)
               FROM red_piece r JOIN verse v ON v.id = r.verse_id JOIN book b ON b.ord = v.book
              ORDER BY r.q_ord, r.verse_id",
        )
        .map_err(sqlerr)?;
    let mut acc: BTreeMap<i64, (String, Vec<i64>, String)> = BTreeMap::new();
    let mut q = st.query([]).map_err(sqlerr)?;
    while let Some(r) = q.next().map_err(sqlerr)? {
        let qo: i64 = r.get(0).map_err(sqlerr)?;
        let vid: i64 = r.get(1).map_err(sqlerr)?;
        let book: String = r.get(2).map_err(sqlerr)?;
        let piece: String = r.get(3).map_err(sqlerr)?;
        let e = acc.entry(qo).or_insert((book, Vec::new(), String::new()));
        e.1.push(vid);
        e.2.push_str(&piece);
    }
    Ok(acc
        .into_iter()
        .map(|(k, (book, vs, text))| {
            (
                k,
                (
                    book,
                    vs.len(),
                    vs[0],
                    *vs.last().unwrap(),
                    text.chars().count(),
                    sha256_hex(text.as_bytes()),
                ),
            )
        })
        .collect())
}

fn osis_ref(books: &BTreeMap<i64, String>, id: i64) -> String {
    format!(
        "{}.{}.{}",
        books.get(&(id / 1_000_000)).cloned().unwrap_or_default(),
        (id / 1000) % 1000,
        id % 1000
    )
}

/// T5. `source_sha256` is the pinned KJV hash; the files' headers must name it.
pub fn compare(
    conn: &Connection,
    chapters_tsv: &str,
    q_tsv: &str,
    source_sha256: &str,
) -> Result<()> {
    let mut c = Collector::default();
    for (name, tsv) in [("kjv-chapters.tsv", chapters_tsv), ("kjv-q.tsv", q_tsv)] {
        if header_value(tsv, "source").as_deref() != Some(source_sha256) {
            c.push(Error::new(
                "T5",
                format!("{name} was not generated from the pinned source"),
            ));
        }
    }
    let got = chapter_lines(conn)?;
    let want = rows(chapters_tsv);
    if got.len() != want.len() {
        c.push(Error::new(
            "T5",
            format!(
                "{} chapters in the database, {} in kjv-chapters.tsv",
                got.len(),
                want.len()
            ),
        ));
    }
    for (g, w) in got.iter().zip(&want) {
        if g != w {
            let chapter = w.split('\t').next().unwrap_or("?");
            let cols = [
                "chapter",
                "verses",
                "text_sha256",
                "marks",
                "red",
                "words_sha256",
            ];
            let which: Vec<&str> = g
                .split('\t')
                .zip(w.split('\t'))
                .zip(cols)
                .filter(|((a, b), _)| a != b)
                .map(|(_, n)| n)
                .collect();
            c.push(Error::new(
                "T5",
                format!("kjv-chapters.tsv: chapter {chapter} differs in {which:?}"),
            ));
        }
    }
    let mut books: BTreeMap<i64, String> = BTreeMap::new();
    let mut st = conn.prepare("SELECT ord, osis FROM book").map_err(sqlerr)?;
    for r in st
        .query_map([], |r| Ok((r.get(0)?, r.get(1)?)))
        .map_err(sqlerr)?
    {
        let (o, n) = r.map_err(sqlerr)?;
        books.insert(o, n);
    }
    let recs = q_records(conn)?;
    let want = rows(q_tsv);
    if recs.len() != want.len() {
        c.push(Error::new(
            "T5",
            format!(
                "{} q_ord values in the database, {} in kjv-q.tsv",
                recs.len(),
                want.len()
            ),
        ));
    }
    for line in want {
        let f: Vec<&str> = line.split('\t').collect();
        if f.len() != 9 {
            c.push(Error::new("T5", "kjv-q.tsv: malformed line"));
            continue;
        }
        let qo: i64 = f[0].parse().unwrap_or(-1);
        match recs.get(&qo) {
            None => c.push(Error::new(
                "T5",
                format!("kjv-q.tsv: q_ord {qo} has no pieces in the database"),
            )),
            Some((book, nv, first, last, cp, sha)) => {
                let g = [
                    book.clone(),
                    nv.to_string(),
                    osis_ref(&books, *first),
                    osis_ref(&books, *last),
                    cp.to_string(),
                    sha.clone(),
                ];
                let w = [f[1], f[4], f[5], f[6], f[7], f[8]];
                if g.iter().map(String::as_str).ne(w.iter().copied()) {
                    c.push(Error::new(
                        "T5",
                        format!("kjv-q.tsv: q_ord {qo} differs (database {g:?}, oracle {w:?})"),
                    ));
                }
            }
        }
    }
    c.finish()
}

// ------------------------------------------------------------------ lexicons

/// The database's lexicon-entries.tsv lines (without header), serialised the
/// way `docs/pipeline/survey-scripts/oracle_lexicons.py` does from the raw
/// bytes: OSHB then MGNT, each in file order; the entry's own attribute is
/// rebuilt from the key under the pinned spelling.
pub fn lexicon_lines(conn: &Connection) -> std::result::Result<Vec<String>, Error> {
    let mut entries: Vec<(String, String, i64)> = Vec::new();
    let mut st = conn
        .prepare(
            "SELECT key, lexicon, ord FROM lex_entry
              ORDER BY CASE lexicon WHEN 'LEX-HEB-OSHB' THEN 0 ELSE 1 END, ord",
        )
        .map_err(sqlerr)?;
    for r in st
        .query_map([], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)))
        .map_err(sqlerr)?
    {
        entries.push(r.map_err(sqlerr)?);
    }
    type Node = (i64, Option<i64>, Option<String>, Option<String>);
    let mut nodes: BTreeMap<String, Vec<Node>> = BTreeMap::new();
    let mut st = conn
        .prepare("SELECT key, n, parent, name, text FROM lex_node ORDER BY key, n")
        .map_err(sqlerr)?;
    let mut rows = st.query([]).map_err(sqlerr)?;
    while let Some(r) = rows.next().map_err(sqlerr)? {
        nodes.entry(r.get(0).map_err(sqlerr)?).or_default().push((
            r.get(1).map_err(sqlerr)?,
            r.get(2).map_err(sqlerr)?,
            r.get(3).map_err(sqlerr)?,
            r.get(4).map_err(sqlerr)?,
        ));
    }
    let mut attrs: BTreeMap<(String, i64), Vec<(String, String)>> = BTreeMap::new();
    let mut st = conn
        .prepare("SELECT key, n, name, value FROM lex_attr ORDER BY key, n, i")
        .map_err(sqlerr)?;
    let mut rows = st.query([]).map_err(sqlerr)?;
    while let Some(r) = rows.next().map_err(sqlerr)? {
        attrs
            .entry((r.get(0).map_err(sqlerr)?, r.get(1).map_err(sqlerr)?))
            .or_default()
            .push((r.get(2).map_err(sqlerr)?, r.get(3).map_err(sqlerr)?));
    }
    let mut out = Vec::with_capacity(entries.len());
    for (key, lexicon, ord) in entries {
        let own = if lexicon == crate::lexicon::OSHB_ID {
            format!("entry@id={key}")
        } else {
            let n: u32 = key[1..].parse().unwrap_or(0);
            format!("entry@strongs={n:05}")
        };
        let mut attr_list = vec![own];
        let mut text: Vec<u8> = Vec::new();
        let mut tree: Vec<u8> = Vec::new();
        // Open elements: (n, name).
        let mut open: Vec<(i64, String)> = Vec::new();
        let list = nodes.get(&key).map(Vec::as_slice).unwrap_or(&[]);
        for (n, parent, name, t) in list {
            while open.last().map(|o| o.0) != *parent {
                let Some((_, closed)) = open.pop() else {
                    return Err(Error::new(
                        "T5",
                        format!("entry {key}: broken parent chain"),
                    ));
                };
                tree.extend_from_slice(format!("</{closed}>").as_bytes());
            }
            match (name, t) {
                (Some(name), None) => {
                    for (a, v) in attrs
                        .get(&(key.clone(), *n))
                        .map(Vec::as_slice)
                        .unwrap_or(&[])
                    {
                        attr_list.push(format!("{name}@{a}={v}"));
                    }
                    tree.extend_from_slice(format!("<{name}>").as_bytes());
                    open.push((*n, name.clone()));
                }
                (None, Some(t)) => {
                    text.extend_from_slice(t.as_bytes());
                    tree.extend_from_slice(t.as_bytes());
                }
                _ => return Err(Error::new("T5", format!("entry {key}: malformed node"))),
            }
        }
        while let Some((_, closed)) = open.pop() {
            tree.extend_from_slice(format!("</{closed}>").as_bytes());
        }
        out.push(
            [
                key,
                lexicon,
                ord.to_string(),
                text.len().to_string(),
                sha256_hex(&text),
                attr_list.len().to_string(),
                sha256_hex(attr_list.join("\n").as_bytes()),
                sha256_hex(&tree),
            ]
            .join("\t"),
        );
    }
    Ok(out)
}

/// T5 for content.sqlite: the database equals `lexicon-entries.tsv` entry by
/// entry. `sources` are the pinned (ID, file, SHA-256) of both lexicons; the
/// file's header must name exactly them.
pub fn compare_lexicons(
    conn: &Connection,
    tsv: &str,
    sources: &[(&str, &str, &str)],
) -> Result<()> {
    let mut c = Collector::default();
    let header: Vec<&str> = tsv.lines().take_while(|l| l.starts_with('#')).collect();
    for (id, file, sha) in sources {
        let want = format!("# source: {id} {file} sha256 {sha}");
        if !header.contains(&want.as_str()) {
            c.push(Error::new(
                "T5",
                format!("lexicon-entries.tsv was not generated from the pinned {id}"),
            ));
        }
    }
    let got = lexicon_lines(conn)?;
    let want = rows(tsv);
    if got.len() != want.len() {
        c.push(Error::new(
            "T5",
            format!(
                "{} entries in the database, {} in lexicon-entries.tsv",
                got.len(),
                want.len()
            ),
        ));
    }
    let cols = [
        "key",
        "lexicon",
        "ord",
        "text_bytes",
        "text_sha256",
        "attr_count",
        "attr_sha256",
        "tree_sha256",
    ];
    let mut bad = 0usize;
    for (g, w) in got.iter().zip(&want) {
        if g != w {
            bad += 1;
            if bad <= 10 {
                let key = w.split('\t').next().unwrap_or("?");
                let which: Vec<&str> = g
                    .split('\t')
                    .zip(w.split('\t'))
                    .zip(cols)
                    .filter(|((a, b), _)| a != b)
                    .map(|(_, n)| n)
                    .collect();
                c.push(Error::new(
                    "T5",
                    format!("lexicon-entries.tsv: entry {key} differs in {which:?}"),
                ));
            }
        }
    }
    if bad > 10 {
        c.push(Error::new(
            "T5",
            format!("{bad} lexicon entries differ in all"),
        ));
    }
    c.finish()
}

// ------------------------------------------------------------------ commentary

/// The database's mhcc-blocks.tsv and mhcc-anchors.tsv lines (without
/// header), computed from the stored rows alone: each block's raw bytes are
/// rebuilt by [`crate::commentary::serialise_block`], its text is its text
/// nodes in order, and each anchor's osisID is its stored verse ids spelled
/// `Book.C.V`.
pub fn cmt_lines(conn: &Connection) -> std::result::Result<(Vec<String>, Vec<String>), Error> {
    use crate::commentary::{AttrRow, NodeRow, osis_ref, serialise_block};
    use crate::profile::KJV_BOOKS;
    let mut nodes: BTreeMap<i64, Vec<NodeRow>> = BTreeMap::new();
    let mut st = conn
        .prepare("SELECT block, parent, name, text FROM cmt_node ORDER BY block, n")
        .map_err(sqlerr)?;
    let mut q = st.query([]).map_err(sqlerr)?;
    while let Some(r) = q.next().map_err(sqlerr)? {
        nodes.entry(r.get(0).map_err(sqlerr)?).or_default().push((
            r.get(1).map_err(sqlerr)?,
            r.get(2).map_err(sqlerr)?,
            r.get(3).map_err(sqlerr)?,
        ));
    }
    let mut attrs: BTreeMap<i64, Vec<AttrRow>> = BTreeMap::new();
    let mut st = conn
        .prepare("SELECT block, n, name, value FROM cmt_attr ORDER BY block, n, i")
        .map_err(sqlerr)?;
    let mut q = st.query([]).map_err(sqlerr)?;
    while let Some(r) = q.next().map_err(sqlerr)? {
        attrs.entry(r.get(0).map_err(sqlerr)?).or_default().push((
            r.get(1).map_err(sqlerr)?,
            r.get(2).map_err(sqlerr)?,
            r.get(3).map_err(sqlerr)?,
        ));
    }
    let mut blocks = Vec::new();
    let mut span: BTreeMap<i64, (i64, i64)> = BTreeMap::new();
    let mut st = conn
        .prepare("SELECT id, book, chapter, anchor FROM cmt_block ORDER BY id")
        .map_err(sqlerr)?;
    let mut q = st.query([]).map_err(sqlerr)?;
    let dash = |v: Option<i64>| v.map_or("-".to_string(), |x| x.to_string());
    while let Some(r) = q.next().map_err(sqlerr)? {
        let id: i64 = r.get(0).map_err(sqlerr)?;
        let book: i64 = r.get(1).map_err(sqlerr)?;
        let chapter: Option<i64> = r.get(2).map_err(sqlerr)?;
        let anchor: Option<i64> = r.get(3).map_err(sqlerr)?;
        if let Some(a) = anchor {
            span.entry(a).or_insert((id, id)).1 = id;
        }
        let n = nodes.get(&id).map(Vec::as_slice).unwrap_or(&[]);
        let a = attrs.get(&id).map(Vec::as_slice).unwrap_or(&[]);
        let raw = serialise_block(n, a);
        let text: String = n.iter().filter_map(|x| x.2.as_deref()).collect();
        let name = n.first().and_then(|x| x.1.clone()).unwrap_or_default();
        let sig: Vec<String> = a
            .iter()
            .filter(|x| x.0 == 0)
            .map(|x| format!("{}={}", x.1, x.2))
            .collect();
        let sig = if sig.is_empty() {
            "-".to_string()
        } else {
            sig.join(";")
        };
        let bname = usize::try_from(book - 1)
            .ok()
            .and_then(|b| KJV_BOOKS.get(b))
            .map_or("?", |b| b.0);
        blocks.push(format!(
            "{id}\t{bname}\t{}\t{}\t{name}\t{sig}\t{}\t{}\t{}\t{}",
            dash(chapter),
            dash(anchor),
            raw.len(),
            sha256_hex(raw.as_bytes()),
            text.len(),
            sha256_hex(text.as_bytes())
        ));
    }
    let mut verses: BTreeMap<i64, Vec<String>> = BTreeMap::new();
    let mut st = conn
        .prepare("SELECT anchor, verse_id FROM cmt_anchor_verse ORDER BY anchor, k")
        .map_err(sqlerr)?;
    let mut q = st.query([]).map_err(sqlerr)?;
    while let Some(r) = q.next().map_err(sqlerr)? {
        let v: i64 = r.get(1).map_err(sqlerr)?;
        verses
            .entry(r.get(0).map_err(sqlerr)?)
            .or_default()
            .push(osis_ref(u32::try_from(v).unwrap_or(0)));
    }
    let mut anchors = Vec::new();
    let mut st = conn
        .prepare("SELECT id, sid FROM cmt_anchor ORDER BY id")
        .map_err(sqlerr)?;
    let mut q = st.query([]).map_err(sqlerr)?;
    while let Some(r) = q.next().map_err(sqlerr)? {
        let id: i64 = r.get(0).map_err(sqlerr)?;
        let sid: String = r.get(1).map_err(sqlerr)?;
        let (first, last) = span.get(&id).copied().unwrap_or((0, 0));
        let v = verses.get(&id).cloned().unwrap_or_default();
        anchors.push(format!(
            "{id}\t{sid}\t{first}\t{last}\t{}\t{}",
            v.len(),
            v.join(" ")
        ));
    }
    Ok((blocks, anchors))
}

/// Line-by-line comparison of `got` with an oracle file's rows; at most ten
/// differences are named (by their first column and the differing columns).
fn compare_rows(
    c: &mut Collector,
    file: &str,
    got: &[String],
    tsv: &str,
    source: (&str, &str, &str),
    cols: &[&str],
) {
    let want_src = format!("# source: {} {} sha256 {}", source.0, source.1, source.2);
    if !tsv
        .lines()
        .take_while(|l| l.starts_with('#'))
        .any(|l| l == want_src)
    {
        c.push(Error::new(
            "T5",
            format!("{file} was not generated from the pinned {}", source.0),
        ));
    }
    let want = rows(tsv);
    if got.len() != want.len() {
        c.push(Error::new(
            "T5",
            format!(
                "{} rows in the database, {} in {file}",
                got.len(),
                want.len()
            ),
        ));
    }
    let mut bad = 0usize;
    for (g, w) in got.iter().zip(&want) {
        if g != w {
            bad += 1;
            if bad <= 10 {
                let key = w.split('\t').next().unwrap_or("?");
                let which: Vec<&str> = g
                    .split('\t')
                    .zip(w.split('\t'))
                    .zip(cols)
                    .filter(|((a, b), _)| a != b)
                    .map(|(_, n)| *n)
                    .collect();
                c.push(Error::new(
                    "T5",
                    format!("{file}: row {key} differs in {which:?}"),
                ));
            }
        }
    }
    if bad > 10 {
        c.push(Error::new(
            "T5",
            format!("{bad} rows of {file} differ in all"),
        ));
    }
}

/// T5 for a commentary database: its blocks and anchors equal mhcc-blocks.tsv
/// and mhcc-anchors.tsv (generated by `oracle_mhcc.py` from `source` =
/// (id, file, sha256)).
pub fn compare_cmt(
    conn: &Connection,
    blocks_tsv: &str,
    anchors_tsv: &str,
    source: (&str, &str, &str),
) -> Result<()> {
    let mut c = Collector::default();
    let (blocks, anchors) = cmt_lines(conn)?;
    compare_rows(
        &mut c,
        "mhcc-blocks.tsv",
        &blocks,
        blocks_tsv,
        source,
        &[
            "ord",
            "book",
            "chapter",
            "anchor",
            "name",
            "attrs",
            "raw_bytes",
            "raw_sha256",
            "text_bytes",
            "text_sha256",
        ],
    );
    compare_rows(
        &mut c,
        "mhcc-anchors.tsv",
        &anchors,
        anchors_tsv,
        source,
        &[
            "ord",
            "sid",
            "first_block",
            "last_block",
            "verses",
            "osisID",
        ],
    );
    c.finish()
}
